//
// Guard de rotas (src/routers/index.ts). A sessão é simulada pelo stub de GET /auth/me,
// sem passar pela tela de login — nenhum teste aqui depende do backend.

describe('Rotas protegidas', () => {
  it('visitante abre rota privada → é mandado para o login com o destino em ?redirect', () => {
    cy.stubSemSessao()

    cy.visit('/carteira')

    cy.location('pathname').should('eq', '/login')
    cy.location('search').should('include', 'redirect=%2Fcarteira')
  })

  it('visitante faz login vindo de uma rota privada → volta para o destino original', () => {
    const credenciais = { email: 'maria@teste.com', senha: 'senha-correta' }
    cy.stubLogin(credenciais)

    cy.visit('/carteira')
    cy.location('pathname').should('eq', '/login')

    cy.get('[data-cy="login-email"]').type(credenciais.email)
    cy.get('[data-cy="login-senha"]').type(credenciais.senha)
    cy.get('[data-cy="login-submit"]').click()

    cy.location('pathname').should('eq', '/carteira')
  })

  it('cliente logado abre /login → é redirecionado para o painel', () => {
    cy.stubSessao('cliente')

    cy.visit('/login')

    cy.location('pathname').should('eq', '/')
  })

  it('cliente logado abre área admin → vê a tela de acesso restrito', () => {
    cy.stubSessao('cliente')

    cy.visit('/admin')

    cy.location('pathname').should('eq', '/403')
  })

  it('admin logado abre área admin → permanece nela', () => {
    cy.stubSessao('admin')

    cy.visit('/admin')

    cy.location('pathname').should('eq', '/admin')
  })
})
